#include "Aevrynd/ReplicationRuntime3D.h"
#include <algorithm>
#include <cmath>
#include <stdexcept>

namespace Aevrynd {namespace {
bool Valid(const ReplicationRuntimeSettings3D&s){return s.tickRate&&s.maximumClients&&s.maximumInputHistory&&s.maximumSnapshotHistory&&s.maximumPacketsPerTick&&std::isfinite(s.movementPerTick)&&s.movementPerTick>0;}
void Move(ReplicationPlayerState3D&state,const ReplicationInputCommand3D&input,float scale){Vec3 delta{float(input.moveX)/32767.f*scale,0,float(input.moveZ)/32767.f*scale};GlobalPosition3D next{};if(AddGlobalPosition3D(state.position,delta,next)){state.position=next;state.velocity=delta;}state.tick=input.tick;}
}
ReplicationServer3D::ReplicationServer3D(LoopbackNetworkTransport3D&t,NetworkEndpoint3D e,std::uint64_t epoch,ReplicationRuntimeSettings3D s):transport_(t),endpoint_(e),sessionEpoch_(epoch),settings_(s){if(!e||!epoch||!Valid(s))throw std::invalid_argument("Invalid replication server settings");}
bool ReplicationServer3D::AddClient(std::uint32_t id,NetworkEndpoint3D endpoint,GlobalPosition3D spawn){if(!id||!endpoint||clients_.size()>=settings_.maximumClients||clients_.contains(id)||!NormalizeGlobalPosition3D(spawn))return false;Client c{};c.endpoint=endpoint;c.player={{sessionEpoch_,id},spawn,{},0};clients_.emplace(id,std::move(c));return true;}
void ReplicationServer3D::Receive(){NetworkPacket3D packet;for(std::size_t n=0;n<settings_.maximumPacketsPerTick&&transport_.TryReceive(endpoint_,packet);++n){ReplicationMessage3D message;if(!DecodeReplicationPacket3D(packet.bytes,message)){++stats_.packetRejects;continue;}if(auto*input=std::get_if<ReplicationInputCommand3D>(&message)){auto found=clients_.find(input->clientId);if(found==clients_.end()||packet.source!=found->second.endpoint||input->sessionEpoch!=sessionEpoch_){++stats_.packetRejects;continue;}auto&c=found->second;if(input->tick+settings_.maximumInputHistory<tick_){++stats_.staleInputs;continue;}if(input->tick>tick_+settings_.maximumInputHistory){++stats_.futureInputs;continue;}if(input->sequence<=c.lastInputSequence||c.inputs.contains(input->tick)){++stats_.duplicateInputs;continue;}c.lastInputSequence=input->sequence;c.inputs.emplace(input->tick,*input);while(c.inputs.size()>settings_.maximumInputHistory){c.inputs.erase(c.inputs.begin());++stats_.historyDrops;}++stats_.inputsReceived;}else if(auto*ack=std::get_if<ReplicationAck3D>(&message)){auto found=clients_.find(ack->clientId);if(found==clients_.end()||packet.source!=found->second.endpoint||ack->sessionEpoch!=sessionEpoch_){++stats_.packetRejects;continue;}found->second.ackSnapshotTick=(std::max)(found->second.ackSnapshotTick,ack->snapshotTick);++stats_.acks;}else ++stats_.packetRejects;}}
void ReplicationServer3D::SendSnapshots(){for(auto&[id,c]:clients_){ReplicationSnapshot3D s{};s.sessionEpoch=sessionEpoch_;s.serverTick=tick_;s.clientId=id;s.interestEpoch=c.interestEpoch;s.originGeneration=1;s.baselineTick=c.ackSnapshotTick;const auto baseline=std::ranges::find_if(c.snapshots,[&](const auto&x){return x.serverTick==c.ackSnapshotTick;});s.full=c.ackSnapshotTick==0||baseline==c.snapshots.end();for(const auto&[otherId,other]:clients_){ReplicatedEntityState3D state{other.player.entity,other.player.position,other.player.velocity,otherId==id?1u:0u};bool changed=s.full;if(!changed){const auto previous=std::ranges::find_if(baseline->entities,[&](const auto&value){return value.id==state.id;});changed=previous==baseline->entities.end()||previous->position!=state.position||previous->velocity.x!=state.velocity.x||previous->velocity.y!=state.velocity.y||previous->velocity.z!=state.velocity.z||previous->flags!=state.flags;}if(changed)s.entities.push_back(state);}std::vector<std::byte> bytes;if(!EncodeReplicationPacket3D(s,bytes)||!transport_.Send(endpoint_,c.endpoint,bytes)){++stats_.packetRejects;continue;}ReplicationSnapshot3D stored=s;if(!s.full){stored.entities=baseline->entities;for(const auto&entity:s.entities){auto found=std::ranges::find_if(stored.entities,[&](const auto&value){return value.id==entity.id;});if(found==stored.entities.end())stored.entities.push_back(entity);else *found=entity;}}c.snapshots.push_back(std::move(stored));while(c.snapshots.size()>settings_.maximumSnapshotHistory)c.snapshots.pop_front();++stats_.snapshotsSent;if(s.full)++stats_.fullSnapshots;else ++stats_.deltaSnapshots;}}
void ReplicationServer3D::Tick(){Receive();++tick_;for(auto&[id,c]:clients_){ReplicationInputCommand3D input{sessionEpoch_,tick_,c.lastInputSequence,id,0,0,0,false};if(auto found=c.inputs.find(tick_);found!=c.inputs.end()){input=found->second;c.inputs.erase(found);c.lastInputTick=tick_;}Move(c.player,input,settings_.movementPerTick);}SendSnapshots();++stats_.ticks;}
std::optional<ReplicationPlayerState3D> ReplicationServer3D::Player(std::uint32_t id)const{auto found=clients_.find(id);if(found==clients_.end())return{};return found->second.player;}

ReplicationClient3D::ReplicationClient3D(LoopbackNetworkTransport3D&t,NetworkEndpoint3D e,NetworkEndpoint3D server,std::uint64_t epoch,std::uint32_t id,ReplicationRuntimeSettings3D s):transport_(t),endpoint_(e),server_(server),sessionEpoch_(epoch),clientId_(id),settings_(s){if(!e||!server||!epoch||!id||!Valid(s))throw std::invalid_argument("Invalid replication client settings");predicted_.entity={epoch,id};}
bool ReplicationClient3D::SubmitInput(std::int16_t x,std::int16_t z,bool jump){pending_={sessionEpoch_,tick_+1,sequence_+1,clientId_,x,z,0,jump};return true;}
void ReplicationClient3D::Simulate(ReplicationPlayerState3D&s,const ReplicationInputCommand3D&i)const{Move(s,i,settings_.movementPerTick);}
void ReplicationClient3D::Apply(const ReplicationSnapshot3D&s){if(s.sessionEpoch!=sessionEpoch_||s.clientId!=clientId_||s.serverTick<=latestSnapshotTick_)return;latestSnapshotTick_=s.serverTick;const ReplicatedEntityState3D* own{};for(const auto&e:s.entities){ReplicationPlayerState3D state{e.id,e.position,e.velocity,s.serverTick};if(e.id==predicted_.entity)own=&e;else{auto&pair=remote_[e.id];pair.first=pair.second.entity?pair.second:state;pair.second=state;}}for(auto id:s.despawned)remote_.erase(id);if(own){predicted_={own->id,own->position,own->velocity,s.serverTick};while(!history_.empty()&&history_.front().input.tick<=s.serverTick)history_.pop_front();for(auto&frame:history_){Simulate(predicted_,frame.input);frame.state=predicted_;++stats_.replayedInputs;}++stats_.reconciliations;}ReplicationAck3D ack{sessionEpoch_,s.serverTick,predicted_.tick,clientId_};std::vector<std::byte>bytes;if(EncodeReplicationPacket3D(ack,bytes))transport_.Send(endpoint_,server_,bytes);}
void ReplicationClient3D::Receive(){NetworkPacket3D packet;for(std::size_t n=0;n<settings_.maximumPacketsPerTick&&transport_.TryReceive(endpoint_,packet);++n){ReplicationMessage3D message;if(packet.source!=server_||!DecodeReplicationPacket3D(packet.bytes,message)){++stats_.packetRejects;continue;}if(auto*s=std::get_if<ReplicationSnapshot3D>(&message))Apply(*s);else ++stats_.packetRejects;}}
void ReplicationClient3D::Tick(){Receive();++tick_;ReplicationInputCommand3D input=pending_;if(input.tick!=tick_)input={sessionEpoch_,tick_,sequence_+1,clientId_,0,0,0,false};input.sequence=++sequence_;std::vector<std::byte>bytes;if(EncodeReplicationPacket3D(input,bytes))transport_.Send(endpoint_,server_,bytes);Simulate(predicted_,input);history_.push_back({input,predicted_});while(history_.size()>settings_.maximumInputHistory){history_.pop_front();++stats_.historyDrops;}pending_={};++stats_.ticks;}
std::optional<ReplicationPlayerState3D> ReplicationClient3D::Remote(NetworkEntityId3D id,float alpha)const{auto found=remote_.find(id);if(found==remote_.end())return{};alpha=(std::clamp)(std::isfinite(alpha)?alpha:0.f,0.f,1.f);auto value=found->second.second;Vec3 a{},b{};WorldOrigin3D origin{};origin.position=found->second.first.position;if(ToLocalPosition3D(found->second.first.position,origin,a)&&ToLocalPosition3D(found->second.second.position,origin,b)){GlobalPosition3D p;if(ToGlobalPosition3D(a+(b-a)*alpha,origin,p))value.position=p;}return value;}
}
